    foreach([[401,'failed'],[429,'failed'],[500,'uncertain'],[200,'uncertain']] as [$status,$expected])checkMail(mailjetSend($stored,$message,false,fn()=>[$status,'bad-json'])['status']===$expected,'Safe transport classification');
    $error=mailjetSend($stored,$message,false,fn()=>throw new RuntimeException($variables['password']));checkMail(!str_contains($error['message'],$variables['password']),'Transport errors cannot leak password');
