    $mail=prepareWelcome(['mail_template'=>$t['id'],'creation_token'=>'12345678-1234-1234-1234-123456789012'],'Alex','alex@example.test','user',true,$variables['password'],[]);queueWelcome($mail,'learner',$admin,'alex@example.test');
