    $mail['id']=id();$mail['request']='32345678-1234-1234-1234-123456789012';queueWelcome($mail,'learner',$admin,'alex@example.test');query("UPDATE users SET auth_version=auth_version+1 WHERE id='learner'");checkMail(deliverWelcome($mail['id'],$admin,false,$sender)['status']==='cancelled','Changed credentials invalidate queue');checkMail(one('SELECT payload FROM welcome_mails WHERE id=?',[$mail['id']])['payload']===null,'Invalidated credentials erased');
    $mail['id']=id();$mail['request']='42345678-1234-1234-1234-123456789012';queueWelcome($mail,'learner',$admin,'alex@example.test');query('UPDATE welcome_mails SET created_at=? WHERE id=?',[gmdate('Y-m-d\TH:i:s\Z',time()-86401),$mail['id']]);cleanWelcomeMails();checkMail(welcomeStatus($mail['id'])['status']==='expired','Queue expires after 24 hours');
